import "server-only";
import data from "@/data/agency-agents.json";
import type { AgentTemplate } from "./logic";

/** Agency Agents catalog, generated by scripts/import-agency-agents.mjs (MIT; source + commit recorded in the JSON). */
export const LIBRARY: { source: string; commit: string; license: string; divisions: Record<string, string>; agents: AgentTemplate[] } = data;

export const templateBySlug = (slug: string) => LIBRARY.agents.find((a) => a.slug === slug);
export const divisionLabel = (division: string) => LIBRARY.divisions[division] ?? division;
